-- Additive catalog references only. No updates to immutable historical rows.
-- Apply with the matching web release; no change to RLS or account access.
begin;
-- Read-only capability discovery; no owner data and no mutation authority.
create function public.get_inspiration_reference_ids() returns jsonb
language plpgsql stable security definer set search_path=pg_catalog,public,fluid_private as $$
begin
 if auth.uid() is null then raise exception 'authentication_required' using errcode='28000'; end if;
 return coalesce((select jsonb_agg(id order by id) from fluid_private.inspiration_catalog),'[]'::jsonb);
end $$;
revoke all on function public.get_inspiration_reference_ids() from public,anon,service_role;
grant execute on function public.get_inspiration_reference_ids() to authenticated;
commit;
